<?php

namespace Agent\AgentBundle\Repository;
use Doctrine\ORM\Query\AST\Join;

/**
 * DetachementRepository
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 */
class DetachementRepository extends \Doctrine\ORM\EntityRepository
{

  public function detachlisteImprimer($etat=null, $id=null, $nature=null,$agent=null){
  
  $em = $this->getEntityManager();
  
    $dql=" SELECT d as detachement 
           FROM AgentBundle:Detachement d 
       		WHERE d.naturedetachement = :id
        ";

        if($etat ==1 ){
        	$dql.=" And d.id = ".$nature;
        }else{
        	$dql.=" And 1 = 1 ";
        }
		
		$query = $em->createQuery($dql);
        $query =$query->setParameter('id', $id);

        return $query->getResult();
  }


}
